package com.bank.index;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BstDemo {

    private static final Logger log = Logger.getLogger(BstDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BalanceBST bst = new BalanceBST();

        // Insert balances; the tree keeps them ordered automatically.
        for (String b : new String[]{"250000", "1000000", "50000", "300000", "75000"}) {
            bst.insert(new BigDecimal(b));
        }

        log.info("Balances in sorted order (inorder traversal):");
        bst.inorder();

        BigDecimal target = new BigDecimal("300000");
        log.info(() -> "Contains Rs.300000? " + bst.contains(target));

        BigDecimal missing = new BigDecimal("999999");
        log.info(() -> "Contains Rs.999999? " + bst.contains(missing));
    }
}

