class BalanceBST {

    private static final Logger log = Logger.getLogger(BalanceBST.class.getName());

    // A private node type for the tree.
    private BstNode root;

    void insert(BigDecimal value) {
        root = insertRec(root, value);
        log.info(() -> "Inserted Rs." + value);
    }

    private BstNode insertRec(BstNode node, BigDecimal value) {
        if (node == null) return new BstNode(value);      // empty spot found
        int cmp = value.compareTo(node.value);
        if (cmp < 0) node.left = insertRec(node.left, value);   // smaller → left
        else if (cmp > 0) node.right = insertRec(node.right, value); // larger → right
        // equal → ignore duplicate
        return node;
    }

    boolean contains(BigDecimal value) {
        BstNode node = root;
        while (node != null) {
            int cmp = value.compareTo(node.value);
            if (cmp == 0) return true;      // found
            node = (cmp < 0) ? node.left : node.right; // halve the search
        }
        return false;
    }

    void inorder() { inorderRec(root); }

    private void inorderRec(BstNode node) {
        if (node == null) return;
        inorderRec(node.left);
        log.info(() -> "Rs." + node.value);
        inorderRec(node.right);
    }
}

// ─── Would be in structure/BstNode.java in a real project ───
class BstNode {
    final BigDecimal value;
    BstNode left;
    BstNode right;
    BstNode(BigDecimal value) { this.value = value; }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
